import { describe, it, expect, beforeAll } from "vitest";
import axe from "axe-core";
import { renderRecipePage } from "../src/page.js";

// jsdom has no layout engine / rendering pipeline, so axe cannot compute
// actual foreground/background colors for the color-contrast rule.
// We exclude it here rather than pretending it passed; contrast must be
// verified with a tool that renders (e.g. axe browser extension / pa11y).
const IGNORED_RULES = ["color-contrast"];

// Load axe-core's source and evaluate it in this (jsdom-backed) global scope,
// so we can call window.axe.run(document).
beforeAll(() => {
  const src = readFileSync(require.resolve("axe-core"), "utf8");
  // eslint-disable-next-line no-eval -- simplest way to load the UMD bundle
  (0, eval)(src);
});

function formatViolations(violations) {
  return violations
    .map((v) => `${v.id} (${v.impact}): ${v.help}\n    nodes: ${v.nodes.length}`)
    .join("\n  ");
}

async function runAxe() {
  document.documentElement.innerHTML = renderRecipePage();

  const results = await window.axe.run(document, {
    runOnly: { type: "rule", values: [] },
    rules: Object.fromEntries(IGNORED_RULES.map((id) => [id, { enabled: false }])),
  });
  return results;
}

describe("recipe page accessibility (axe-core)", () => {
  it("has zero violations", async () => {
    const results = await runAxe();
    if (results.violations.length > 0) {
      console.error(
        `\nAXE VIOLATIONS (${results.violations.length}):\n  ${formatViolations(results.violations)}\n`
      );
    }
    expect(results.violations).toEqual([]);
  });

  it("page contains expected landmarks and structure", () => {
    document.documentElement.innerHTML = renderRecipePage();
    expect(document.querySelector("nav")).not.toBeNull();
    expect(document.querySelector("main")).not.toBeNull();
    expect(document.querySelector("footer")).not.toBeNull();
    expect(document.querySelectorAll("ol > li").length).toBeGreaterThan(0);
    expect(document.querySelector('input[type="email"]')).not.toBeNull();
  });
});
"})
